// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Milestone 3 of the join-strategy ExecPlan: with {@code rdf4j.lmdb.nativeAccumulateJoin.enabled=true}, a correlated
 * OPTIONAL over a native fragment must be served by ONE accumulated fragment execution instead of one per outer row,
 * with an identical result multiset. The store shape mirrors the plan-09 acceptance benchmark
 * ({@code CorrelatedBenchmark.outerAccumulate}) at unit scale, including outers whose seed has no fragment rows (bare
 * LEFT rows) and a duplicate outer (bag multiplicity).
 */
class LmdbNativeAccumulateJoinTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	/**
	 * The outer side is a subselect so the native compiler declines whole-query fusion and the generic
	 * {@code LeftJoinQueryEvaluationStep} drives the OPTIONAL — the seam the accumulate provider hooks. The
	 * fully-fusable variant (plain BGP outer) stays native end-to-end and must remain untouched by the flag.
	 */
	private static final String ACCUMULATE_QUERY = "SELECT ?outer ?value WHERE {\n"
			+ "  { SELECT ?outer ?seed WHERE { ?outer <" + EX + "seed> ?seed . } }\n"
			+ "  OPTIONAL { ?seed <" + EX + "mid> ?m . ?m <" + EX + "value> ?value . }\n"
			+ "}";

	private static final String NATIVE_FUSED_QUERY = "SELECT ?outer ?value WHERE {\n"
			+ "  ?outer <" + EX + "seed> ?seed .\n"
			+ "  OPTIONAL { ?seed <" + EX + "mid> ?m . ?m <" + EX + "value> ?value . }\n"
			+ "}";

	/**
	 * INNER variant of the accumulate shape: same subselect outer, but the fragment is a plain join — unmatched outers
	 * emit nothing. Serves as the Mode.INNER seam test on {@code JoinQueryEvaluationStep}.
	 */
	private static final String INNER_QUERY = "SELECT ?outer ?value WHERE {\n"
			+ "  { SELECT ?outer ?seed WHERE { ?outer <" + EX + "seed> ?seed . } }\n"
			+ "  ?seed <" + EX + "mid> ?m . ?m <" + EX + "value> ?value .\n"
			+ "}";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc,posc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI seed = vf.createIRI(EX, "seed");
			IRI mid = vf.createIRI(EX, "mid");
			IRI value = vf.createIRI(EX, "value");
			for (int i = 0; i < 40; i++) {
				IRI outer = vf.createIRI(EX, "outer" + i);
				IRI seedNode = vf.createIRI(EX, "seedNode" + i);
				conn.add(outer, seed, seedNode);
				// Outers 0..29 have fragment rows (fan-out 3); 30..39 have none (bare LEFT rows).
				if (i < 30) {
					for (int f = 0; f < 3; f++) {
						IRI m = vf.createIRI(EX, "mid" + i + "_" + f);
						conn.add(seedNode, mid, m);
						conn.add(m, value, vf.createLiteral(i * 10 + f));
					}
				}
			}
			// Duplicate outer edge: outer0 carries a second seed binding to seedNode1 — bag multiplicity.
			conn.add(vf.createIRI(EX, "outer0"), seed, vf.createIRI(EX, "seedNode1"));
		}
		System.setProperty(NATIVE_FLAG, "true");
	}

	@AfterEach
	void tearDown() {
		System.clearProperty(NATIVE_FLAG);
		System.clearProperty(LmdbNativeAccumulateJoin.ENABLED_PROPERTY);
		repository.shutDown();
	}

	@Test
	void correlatedOptionalCollapsesToOneFragmentExecution() {
		List<String> expected = rows(ACCUMULATE_QUERY);
		assertThat(expected).hasSize(30 * 3 + 3 + 10); // 90 matched + outer0's second seed fan-out + 10 bare

		System.setProperty(LmdbNativeAccumulateJoin.ENABLED_PROPERTY, "true");
		LmdbNativeAccumulateJoin.resetMetrics();
		List<String> actual = rows(ACCUMULATE_QUERY);

		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(LmdbNativeAccumulateJoin.BATCHES.get()).as("accumulate batch engaged").isOne();
		assertThat(LmdbNativeAccumulateJoin.FRAGMENT_EXECUTIONS.get())
				.as("the fragment must execute exactly once for the whole outer stream")
				.isOne();
	}

	@Test
	void correlatedInnerJoinCollapsesToOneFragmentExecution() {
		List<String> expected = rows(INNER_QUERY);
		assertThat(expected).hasSize(30 * 3 + 3); // 90 matched + outer0's second seed fan-out; bare outers drop

		System.setProperty(LmdbNativeAccumulateJoin.ENABLED_PROPERTY, "true");
		LmdbNativeAccumulateJoin.resetMetrics();
		List<String> actual = rows(INNER_QUERY);

		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(LmdbNativeAccumulateJoin.BATCHES.get()).as("accumulate batch engaged").isOne();
		assertThat(LmdbNativeAccumulateJoin.FRAGMENT_EXECUTIONS.get())
				.as("the fragment must execute exactly once for the whole outer stream")
				.isOne();
	}

	@Test
	void flagOffKeepsPerRowEvaluationUntouched() {
		LmdbNativeAccumulateJoin.resetMetrics();
		List<String> rows = rows(ACCUMULATE_QUERY);
		assertThat(rows).hasSize(103);
		assertThat(LmdbNativeAccumulateJoin.BATCHES.get()).isZero();
		assertThat(LmdbNativeAccumulateJoin.FRAGMENT_EXECUTIONS.get()).isZero();
	}

	@Test
	void nativeFusedShapeStaysUntouchedByTheFlag() {
		List<String> expected = rows(NATIVE_FUSED_QUERY);

		System.setProperty(LmdbNativeAccumulateJoin.ENABLED_PROPERTY, "true");
		LmdbNativeAccumulateJoin.resetMetrics();
		List<String> actual = rows(NATIVE_FUSED_QUERY);

		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(LmdbNativeAccumulateJoin.BATCHES.get())
				.as("fully native-fused OPTIONAL never reaches the generic seam")
				.isZero();
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (var result = conn.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : bindings.getBindingNames()) {
						parts.add(name + "=" + bindings.getValue(name));
					}
					parts.sort(String::compareTo);
					rows.add(String.join("|", parts));
				}
			}
		}
		return rows;
	}
}
